/* Inter (SIL Open Font License) latin subset, registered with jsPDF for the meeting-brief PDF. */
(function () {
  var F = {};
  F["Inter-400.ttf"] = "";
  F["Inter-600.ttf"] = "";
  F["Inter-700.ttf"] = "";
  window.jspdf.jsPDF.API.events.push(["addFonts", function () {
    this.addFileToVFS("Inter-400.ttf", F["Inter-400.ttf"]); this.addFont("Inter-400.ttf", "Inter", "normal");
    this.addFileToVFS("Inter-600.ttf", F["Inter-600.ttf"]); this.addFont("Inter-600.ttf", "Inter", "semibold");
    this.addFileToVFS("Inter-700.ttf", F["Inter-700.ttf"]); this.addFont("Inter-700.ttf", "Inter", "bold");
  }]);
})();
